insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 1, 'What does a reservoir fluid study contain?', '["One experiment run at several pressures, from which every reported property is derived by interpolation.", "Four or five distinct experiments, each answering a different question about the same sample.", "A set of correlations evaluated at the sample''s own conditions, checked against a small number of spot measurements.", "A single depletion sequence, reported in different units for the reservoir engineer and the facilities engineer."]'::jsonb, 1, 'A compositional analysis, a constant composition expansion, a differential liberation, separator tests, and often viscosity measurements on a coarser grid.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 2, 'Why does a study need more than one experiment?', '["Because the reservoir depletes differentially and the surface separates by flash, and no single procedure represents both.", "Because a single experiment could not possibly cover the whole pressure range from reservoir conditions down to atmospheric.", "Because the laboratory needs replicates to establish the repeatability of each measured quantity.", "Because different experiments are run on different sub-samples, so the set of them tests sample consistency."]'::jsonb, 0, 'In the reservoir, gas that comes out of solution moves away from the oil it left. At the surface the whole stream goes through a separator together and leaves in equilibrium at the separator''s conditions.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 3, 'What does a constant composition expansion do?', '["Expands the sample while removing the liberated gas at each step, which is exactly what makes the overall composition constant.", "Holds the overall composition constant while raising the temperature, so the thermal expansion can be separated out.", "Expands the sample at reservoir temperature with nothing removed at all, recording the total volume against pressure.", "Recombines separator gas and separator liquid at a fixed ratio, which fixes the composition for the other tests."]'::jsonb, 2, 'Because nothing leaves, the overall composition is constant, which is what the name says. Removing the gas at each step is the differential liberation.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 4, 'What is the primary purpose of a constant composition expansion?', '["The formation volume factor, since the cell volume at each pressure is measured directly against a reference.", "The solution gas ratio, since the gas released at each step is collected and measured at standard conditions.", "The oil compressibility, since the slope below the bubble point gives it directly.", "The bubble point, read from the break in the plot of pressure against total volume."]'::jsonb, 3, 'Above the bubble point the sample is a nearly incompressible liquid so the line is steep; below it a compressible gas phase is growing so the line bends. Nothing is collected, so no gas volume is measured.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 5, 'Why can a constant composition expansion not give a solution gas ratio?', '["Because nothing was removed, so no gas was collected and no gas volume was measured.", "Because the experiment is run above the bubble point only, where the solution gas ratio is constant anyway.", "Because the relative volume it reports is referenced to the bubble point rather than to a stock tank barrel.", "Because the gas that comes out remains in contact with the oil, so the two are never separately measurable."]'::jsonb, 0, 'The experiment that gives the cleanest measurement gives neither of the two properties a reservoir engineer uses most. Its relative volume is indeed referenced to the bubble point, which is a different limitation.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 6, 'What makes the differential liberation differential?', '["The pressure is lowered in differential steps small enough that the process is reversible at every stage.", "The liberated gas is REMOVED at each pressure step, so the liquid that remains is progressively stripped of light components.", "The volumes are reported as differences from the bubble point rather than as absolute cell volumes.", "The gas and liquid are analysed separately at each step, so their compositions are differentiated."]'::jsonb, 1, 'That removal is why the process imitates the reservoir: once free gas exceeds its critical saturation it flows, and it flows faster than the oil, so it separates from the oil that released it.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 7, 'What is the differential liberation''s reference volume?', '["The stock tank oil produced through the separator train, which is precisely what makes the two experiments directly comparable.", "The cell volume at the bubble point, which is why the reported factors all equal one there.", "The residual oil at 60 F, left after taking the cell to atmospheric pressure in a series of differential steps and cooling it.", "One reservoir barrel at initial pressure, which is the natural reference for a depletion experiment."]'::jsonb, 2, 'A stock tank barrel is not that. It is what comes out of a separator train, which is a small number of flash stages at chosen pressures, and it is a different volume.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 8, 'Why does using a differential Bod directly as Bo overstate it?', '["Because differential liberation strips more of the intermediate components, so the residual volume is smaller than a stock tank barrel from a well-staged train.", "Because the differential experiment runs at reservoir temperature and a stock tank barrel is defined at 60 F.", "Because the differential experiment removes gas that a separator train would have kept in the liquid phase, so the gas volume is larger.", "Because the differential factors include the gas volume in the numerator, which the stock tank definition excludes."]'::jsonb, 0, 'Dividing by a smaller reference gives numbers that are too large. Take a differential Bod of 1.6, use it as Bo, and you have overstated the formation volume factor by several percent.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 9, 'What does the Amyx correction do?', '["Converts the differential gas volumes from residual-oil to stock-tank basis, leaving the liquid volumes untouched.", "Averages the differential and the flash results, weighted by how much of the journey each is thought to represent.", "Interpolates between the differential liberation and the separator test at every pressure, using the gas gravity as the weight.", "Rescales the differential curve so it passes exactly through the separator test''s value at the bubble point, keeping the differential shape below it."]'::jsonb, 3, 'It is exact at the bubble point by construction and approximate everywhere else. It is a shape from one experiment anchored to a level from another.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 10, 'Why is the combination of the two experiments only ever approximate?', '["Because the two experiments are run on different sub-samples, so a small composition difference is unavoidable.", "Because the real journey is differential in the reservoir and flash through the separators, and the crossover is somewhere in the tubing.", "Because the differential liberation is run at reservoir temperature and the separator test at surface temperature.", "Because the Amyx correction was fitted to a limited set of oils and does not extrapolate outside them."]'::jsonb, 1, 'No laboratory procedure reproduces that exactly, so the industry standard is to measure both bounding processes and combine them by a rule. The rule is a modelling choice.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 11, 'What does a separator test define?', '["The optimum separator pressure for the field''s surface facilities, which is a design output rather than a fluid property.", "The gas gravity to use in the black-oil correlations, since that is what the first stage releases.", "What a stock tank barrel of this fluid actually is, which is the denominator of every reservoir volume the study quotes.", "The producing gas-oil ratio the wells will show, which is what the reservoir engineer compares the model against."]'::jsonb, 2, 'Change the separator train and the oil in place in stock tank barrels changes, on identical rock and identical fluid, because a stock tank barrel has become a different amount of matter.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 12, 'Why is a separator test quoted with its conditions?', '["Because the answer depends on them substantially, so a gas-oil ratio is a property of the fluid AND the separator it went through.", "Because the laboratory is obliged to record them for traceability, even though the fluid''s own properties are entirely independent of them.", "Because the correlations that use the result take the separator pressure as an input, as Vasquez-Beggs does.", "Because different laboratories use different standard conditions, so the base has to be stated to allow comparison."]'::jsonb, 0, 'A high separator pressure keeps intermediates in the liquid at the first stage and then loses them in the tank; a low one releases too much at the first stage. Between them is an optimum.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 13, 'What are the two halves a Bo curve is built from?', '["Shape from the constant composition expansion and level from the differential liberation, anchored at the bubble point.", "Shape from a correlation and level from the separator test, which is why the result is a published method rather than measured.", "Shape from the saturated branch and level from the undersaturated branch, joined at the bubble point.", "Shape from the differential liberation and level from the separator test."]'::jsonb, 3, 'That structure explains why a report with a differential liberation and no separator test is incomplete, and why several separator tests give several different Bo curves from the same differential data.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 14, 'What can a PVT study not tell you?', '["The bubble point at any temperature other than the one the study was run at, which limits its use in a thermal scheme.", "Whether the sample is representative, how the fluid varies across the field, or anything at all about the rock.", "The composition of the liberated gas, since only its gravity is reported rather than a full analysis.", "The oil viscosity, which is measured in a separate laboratory and reported as a different document."]'::jsonb, 1, 'A sample from a well producing below its bubble point has lost gas before it was collected, and its bubble point will read low. The study describes the sample it was given.'),
  ('fluid', 'intermediate', 'module', 'm01-what-a-laboratory-measures', 15, 'In what order should a report be read?', '["Front to back as printed, since the laboratory ordered the sections to reflect the dependencies between them.", "Differential liberation first, since it is the largest table and contains the properties a simulator consumes.", "Composition, then the bubble point, then the separator tests, then the differential liberation.", "Separator tests first, then the composition, since the composition is recombined from the separator streams."]'::jsonb, 2, 'That is the reverse of the order most reports print them in. The differential liberation only means anything once you know what it will be referenced to.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 1, 'What is Core Laboratories report RFL 88001?', '["A synthetic benchmark fluid published by the SPE so that compositional simulators could be compared directly against one another.", "The engine''s own fixture fluid, built to exercise the near-critical branch of its phase envelope tracer.", "A reservoir fluid study on Good Oil Co. Well No. 4 in Samson County, Texas, reproduced in McCain and in Whitson and Brule.", "A field study of the Ekene reservoir, commissioned so this course would have a measured fluid to work on."]'::jsonb, 2, 'Three textbooks reproduce one report. It is complete and unremarkable, which is exactly what a teaching example needs.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 2, 'Why is this study reproduced so often?', '["Because it is complete, having every experiment a teaching example needs, and unremarkable, being an ordinary black oil.", "Because it is the oldest published study for which the original laboratory report scans have remained publicly accessible.", "Because its fluid sits near the critical point, which makes it a demanding test of any equation of state.", "Because it was the first study to report a full compositional analysis alongside the volumetric experiments."]'::jsonb, 0, 'Nothing about it is a special case, which is what you want when the point is the method rather than the fluid.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 3, 'The report quotes pressures in psig on a 14.65 psia base. What is a reported 2620 psig?', '["2634.7 psia, using the standard atmospheric base of 14.7 psia that most reports of the era used.", "2605.35 psia, since a gauge pressure is an absolute pressure less the base rather than plus it.", "It cannot be converted without knowing the elevation, since a gauge base varies with altitude.", "2634.65 psia."]'::jsonb, 3, 'That base of 14.65 rather than 14.696 is a detail of the era and the laboratory. A study reproduced with the wrong base is out by about 15 psi everywhere, which is small enough to look like scatter.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 4, 'What are the study''s four measured headline numbers?', '["A bubble point of 2634.65 psia, an initial pressure of 3200 psia, a solution gas ratio of 400 scf/stb and an oil gravity of 32 API.", "A bubble point of 2634.65 psia at 220 F, a total gas-oil ratio of 768 scf/stb, a stock tank gravity of 40.7 API and a formation volume factor of 1.474 rb/stb.", "A saturation pressure of 2791 psia, a gas-oil ratio of 793.8 scf/stb, a gravity of 31.8 API and a volume factor withheld.", "A reservoir temperature of 220 F, a C7+ molecular weight of 218, a specific gravity of 0.8515 and eleven components."]'::jsonb, 1, 'Every one is tier measured. The second distractor lists Ekene''s designed properties and the third the untuned model''s outputs, neither of which is a laboratory measurement of this fluid.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 5, 'What does the compositional analysis of this fluid report?', '["Eleven identifiable pure hydrocarbon components, each with published critical properties available for look-up.", "A continuous distribution of molecular weights, cut into eleven pseudo-components by the laboratory.", "Eleven entries, nine identifiable substances plus carbon dioxide and nitrogen, ending in a lumped C7+ fraction.", "Nine components plus two inerts, with everything heavier than hexane excluded as insufficiently characterized."]'::jsonb, 2, 'C7+ is the eleventh entry and it is a lump: in a real crude it is hundreds of distinct compounds, reported as one entry with a molecular weight of 218 and a specific gravity of 0.8515.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 6, 'Methane is 0.3647 and C7+ is 0.3329 of this fluid. What does that pair say?', '["That it is a black oil, since a condensate has methane above 0.7 and C7+ below 0.05 and a volatile oil sits between.", "That it is a volatile oil, since a black oil would have methane below 0.3 and a much larger heavy fraction.", "Nothing without the temperature, since the same composition is a black oil or a condensate depending on where it sits relative to its critical point.", "That the analysis is unbalanced, since the two largest entries should not be within a few percent of each other."]'::jsonb, 0, 'Reading those two numbers first is the quickest way to know what kind of fluid a report describes, before reading anything else.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 7, 'How is a wellstream composition obtained?', '["By sampling the wellstream directly downhole, which is why a representative sample requires flow above the bubble point.", "By recombination: the separator gas and the separator liquid are analysed separately and combined in the ratio the separator test measured.", "By chromatography on a single surface sample, corrected to reservoir conditions using the formation volume factor.", "By fitting a molecular weight distribution to the measured C7+ properties and integrating it over the carbon numbers."]'::jsonb, 1, 'That means the reported composition depends on the separator test being right, and a recombination at the wrong gas-oil ratio produces a composition systematically wrong in the light end.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 8, 'How much of this fluid does the C7+ entry carry?', '["A third of the moles and about the same share of the mass, since molecular weight cancels in a mole fraction.", "A tenth of the moles and a third of the mass, which is typical for the heavy end of a black oil.", "It cannot be stated in mass terms, since a lumped fraction has no single molecular weight to convert with.", "A third of the moles and something over two thirds of the mass."]'::jsonb, 3, 'Its molecular weight is 218 against methane''s 16, so the mass share is far above the mole share. One entry out of eleven carries most of the fluid.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 9, 'What has to be done with the C7+ before an equation of state can run?', '["It has to be split into several narrower fractions, since a single lump cannot be characterized reliably.", "It has to be excluded from the flash, since a pseudo-component has no critical point and no fugacity.", "Its two measured properties have to be turned into a full set of pseudo-component properties by correlation.", "Its molecular weight has to be converted into an equivalent carbon number, from which the properties are then looked up."]'::jsonb, 2, 'There is no way to run a compositional model on a real fluid without inventing properties for the heavy fraction. Splitting is an option rather than a requirement and the engine uses one pseudo-component.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 10, 'The optimum separator test ran at 100 psig and 75 F. What does optimum mean here?', '["The separator pressure that maximises stock tank liquid, and therefore maximises stock tank gravity and minimises the total gas-oil ratio.", "The separator pressure at which the gas and the liquid leave the vessel in exact equilibrium, which neither higher nor lower pressures achieve.", "The separator pressure the field''s facilities were actually designed for, so the test represents real operating conditions.", "The separator pressure at which the reported formation volume factor is closest to the differential liberation''s value."]'::jsonb, 0, 'Too low and the first stage releases too much; too high and the intermediates stay in the liquid and then flash off in the tank, where the gas is at atmospheric pressure. Between them is the optimum.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 11, 'Why did the study run four separator tests rather than one?', '["Because a single test cannot establish repeatability, and four replicates give a standard deviation on each quantity.", "Because the optimum cannot be predicted reliably enough to skip measuring it, and the facilities engineer needs the curve rather than the point.", "Because each test uses a different sub-sample, so four tests confirm that the sample was homogeneous.", "Because the differential liberation has to be anchored at four pressures, one for each of its reported columns."]'::jsonb, 1, 'Four tests on the same fluid should also produce a smooth trend in stock tank gravity against separator pressure, so a row that breaks the trend is a measurement to question.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 12, 'The report lists one separator stage. How many flash stages does reproducing the test need?', '["One, since the report lists one stage and the stock tank is where the oil ends up rather than a separation step.", "Three, since the wellstream must first be flashed from reservoir conditions to the separator inlet pressure.", "Four, matching the four separator tests the report contains, run in series from highest pressure to lowest.", "Two: the separator at 114.65 psia and the stock tank at 14.65 psia."]'::jsonb, 3, 'The stock tank is a flash stage even though the report does not call it one, because liquid arriving at 14.65 psia from 114.65 psia releases gas, and that gas is in the reported 768 scf/stb.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 13, 'What happens if the stock tank stage is omitted?', '["The calculation fails outright at initialisation, because a separator train always requires a final stage at atmospheric pressure to terminate.", "The gas-oil ratio comes out too high, because all the gas is attributed to the single stage that remains.", "The gas-oil ratio comes out too low, the stock tank volume too large, and the formation volume factor too small, and nothing fails.", "Nothing measurable changes, because the tank releases only a few percent of the total gas at these conditions."]'::jsonb, 2, 'The model runs, produces a full set of numbers, and every one of them is wrong. That is what makes it the classic error: it is a reading error rather than a physics error.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 14, 'How would you notice a missing stock tank stage?', '["By knowing the reported total gas-oil ratio in advance and seeing the model come in below it.", "By the validator, which refuses a separator train whose last stage is above atmospheric pressure.", "By the material balance identity, which fails when a stage is missing from the train.", "By the stock tank gravity, which comes out far heavier than any plausible crude when a stage is dropped."]'::jsonb, 0, 'A total gas-oil ratio of 700 scf/stb on a 40 API oil is entirely plausible in isolation. It only shows up against a measurement, which is why the comparison is worth making.'),
  ('fluid', 'intermediate', 'module', 'm02-the-good-oil-report', 15, 'What is the honest use of an armed literature gate?', '["It certifies the model as validated for the class of fluids the study belongs to, which is what armed means.", "It confirms a model can return a study''s own numbers within a stated tolerance before it is asked about anything the study did not measure.", "It replaces the need for a laboratory measurement on a new fluid, since the model has been shown to work on a real one.", "It fixes the tolerances the model''s own predictions should be quoted with, since those were established by the gate."]'::jsonb, 1, 'A model that cannot reproduce a study whose conditions it has been given exactly is not ready to be trusted elsewhere. Reproducing one study says nothing about certifying a class of fluids.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 1, 'What does an equation of state need for every component?', '["A molecular weight, a specific gravity and a boiling point, which are the three a laboratory reports for each cut.", "A critical temperature, a critical pressure, an acentric factor and a volume shift, plus a binary interaction parameter against every other component.", "A mole fraction and a molecular weight, from which the mixing rules derive everything else internally.", "A critical volume and a parachor, which are what the transport and interfacial models consume."]'::jsonb, 1, 'For methane those are looked up. For C7+ they have to be manufactured, because C7+ is not a substance and has no critical point.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 2, 'What does the engine build the C7+ pseudo-component from?', '["Two measured numbers, a molecular weight of 218 and a specific gravity of 0.8515, through six published correlations.", "A fitted molecular weight distribution, integrated over the carbon numbers to give a weighted average for each property.", "The reported mole fraction and the mixture''s own critical properties, scaled by the heavy end''s mass share.", "A lookup against the nearest normal alkane by molecular weight, with a correction for the aromaticity."]'::jsonb, 0, 'Eight numbers come out of two: boiling point, critical temperature and pressure, acentric factor, volume shift, critical volume, parachor and the Watson characterization factor.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 3, 'In what order does the characterization chain run?', '["Criticals first from the molecular weight, then the boiling point, then the acentric factor from both.", "Acentric factor first from the specific gravity, then the criticals, then the boiling point by inversion.", "All three in parallel from the molecular weight and specific gravity, since each has its own correlation.", "Boiling point first, then the criticals, then the acentric factor."]'::jsonb, 3, 'Each step consumes the previous step''s output, so uncertainty compounds in a specific direction: the acentric factor inherits everything wrong with the criticals, which inherit everything wrong with the boiling point.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 4, 'Why is a measured boiling point worth asking a laboratory for?', '["Because the correlations that follow it were fitted on measured boiling points rather than on correlated ones.", "Because it is the only property of a plus fraction that can be measured directly, the others being constructs.", "Because it short-circuits the least constrained link in the chain and improves everything downstream of it.", "Because it fixes the Watson characterization factor, which is what the engine uses to select the correlation family."]'::jsonb, 2, 'The boiling point is being predicted from a molecular weight and a density for a mixture that has no single boiling point. The engine accepts a measured one and skips the Soreide step, which is the right precedence.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 5, 'The Watson K for Good Oil''s C7+ comes out at 11.73724869095868. What does that tell you?', '["A normal, slightly naphthenic crude heavy end, which is the free sanity check on the two measured inputs.", "An unusually aromatic heavy end, which would explain the model''s later difficulty with the liquid density.", "That the molecular weight and specific gravity are inconsistent, since a normal crude sits near 9 or near 14.", "Nothing useful, since the Watson factor is a refining quantity with no meaning for a reservoir fluid."]'::jsonb, 0, 'Around 12.5 means paraffinic, 11.5 naphthenic and 10 aromatic. A value of 9 or 14 would say the two inputs are inconsistent with any ordinary crude and the arithmetic should be checked before the model runs.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 6, 'Which of the criticals is the less reliable, and why?', '["The critical temperature, because it depends directly on the correlated boiling point and therefore inherits the whole of the first link''s error.", "The critical pressure, because it falls steeply with molecular weight and the correlations disagree more at the heavy end than anywhere else.", "Neither is less reliable; both come from the same Kesler-Lee correlation on the same two inputs.", "The critical pressure, because it is used in both the a and the b parameter and so is exercised twice."]'::jsonb, 1, 'The relationship between a boiling point and a critical temperature is strong and well behaved for pure hydrocarbons, so the critical temperature is the better of the two. 262 psia for this pseudo is a low critical pressure and is where the correlations are least tested.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 7, 'What does the acentric factor do in the equation of state?', '["It scales the covolume, so that a less spherical molecule occupies proportionally more space.", "It sets the binary interaction parameter against methane, which is why heavy components need large values.", "It decides how fast the attraction term weakens with temperature, through the kappa in the alpha function.", "It corrects the critical compressibility from the two-parameter value toward the substance''s real one."]'::jsonb, 2, 'That is its whole role. Good Oil''s C7+ comes out at 0.6690835265426222, against methane near 0.011 and normal decane near 0.49, which is what a heavy non-spherical average should look like.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 8, 'The engine carries two acentric factor correlations. What does that mean in practice?', '["Use the average of the two, since neither one is preferred for a pseudo-component and averaging is the neutral choice.", "Use Edmister, since it is the simpler of the two and the extra terms in Lee-Kesler are not justified for a lump.", "It means nothing for a plus fraction, since both reduce to the same expression when no boiling point is measured.", "Name which one produced your number, because Lee-Kesler and Edmister are both published and give different answers."]'::jsonb, 3, 'The engine''s default is Lee-Kesler. This is the same pattern the course keeps finding: two published methods for one quantity, and the answer is not defined until the method is named.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 9, 'What problem does volume translation fix?', '["A two-parameter cubic reproduces phase equilibrium well and liquid density badly, typically several percent and systematically.", "A cubic returns three real roots inside the two-phase region, and the middle one has to be removed before the volumes are usable.", "A cubic cannot represent the volume of a pseudo-component at all, since it has no measured critical volume.", "A cubic predicts the vapour density badly at high pressure, where the molecules'' own volume dominates."]'::jsonb, 0, 'That is structural: two parameters cannot satisfy both the equilibrium behaviour and the volumetric behaviour across a wide range, and the equation was fitted to prioritise the first.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 10, 'Why is a constant volume translation free?', '["Because it is applied after the flash has converged, so it cannot influence an iteration that has already finished.", "Because the shifts are small enough that their effect on the equilibrium falls below the solver''s tolerance.", "Because it changes the fugacity of every component in a phase by the same factor, so the ratio across the phases and therefore the split are untouched.", "Because it is applied only to the liquid phase, and the vapour phase carries the equilibrium condition."]'::jsonb, 2, 'Most corrections to a model trade one error for another. This one improves the densities and provably leaves the phase behaviour alone, which is an unusually clean result.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 11, 'Jhaveri-Youngren gives Good Oil''s C7+ a volume shift of 0.15389683656773767. What does that say?', '["That the pseudo-component is about fifteen percent denser than a normal alkane carrying that same molecular weight would be.", "That the untranslated equation predicts a molar volume about fifteen percent larger than it should for this material.", "That fifteen percent of the C7+ fraction is unaccounted for by the reported molecular weight and gravity.", "That the shift is at the upper end of its published range and should be treated as a screening value."]'::jsonb, 1, 'It is a large shift, and it is the scale of the problem the translation exists to fix. The correlation is applied to the characterized molecular weight in the same way it would be for a library component.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 12, 'Where does the volume shift correlation go wrong on this fluid?', '["It was fitted at atmospheric conditions and is being applied at 220 F and 2634.65 psia, well outside its range.", "It was fitted for paraffins and this heavy end is naphthenic, which the Watson factor of 11.74 already showed.", "It assumes the shift is constant with pressure, which is a poor approximation near the saturation pressure.", "It was fitted to pure hydrocarbons and well-defined petroleum fractions, and a single lump standing for a whole C7+ distribution is neither."]'::jsonb, 3, 'The engine''s own fixture note gives the mechanism: the pure C7+ pseudo recovers a standard-condition specific gravity of 0.9075 against the defined 0.8515.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 13, 'What does splitting the plus fraction buy?', '["Better behaviour near the critical region, better condensate liquid dropout, and sometimes better liquid densities on narrower cuts.", "A smaller residual in any regression, since more pseudo-components means more parameters to fit with.", "A defensible critical point for the mixture, which a single lumped component cannot provide at all.", "Agreement with the reported molecular weight distribution, which a single lump discards entirely."]'::jsonb, 0, 'A single lump has one critical temperature, so it cannot represent a heavy end whose components differ widely in volatility, and near the critical point that matters.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 14, 'What does splitting cost?', '["Computational cost, since a six-component split multiplies every flash by roughly a factor of six.", "Compatibility, since a split composition can no longer be compared against the laboratory''s reported analysis.", "Unmeasurable choices about the distribution and the cut points, more parameters to tune, and a model nobody can check.", "Accuracy at the light end, since the extra pseudo-components necessarily dilute the mole fractions of the identified species."]'::jsonb, 2, 'A split that reproduces the study perfectly may be doing so by construction rather than by physics, and there is no independent way to find out. A regression with that much freedom will fit the noise.'),
  ('fluid', 'intermediate', 'module', 'm03-characterizing-the-plus-fraction', 15, 'What is the general principle behind stating and measuring the cost of a simplification?', '["A simplification should be stated only when its cost is material, since caveats on negligible effects dilute the report.", "A stated simplification with no measured cost is a caveat a reader cannot act on, and a measured error with no stated simplification is a mystery.", "A simplification should be removed rather than documented, since a documented limitation is one nobody will read.", "A simplification''s cost should be estimated by a sensitivity study rather than measured directly, since a measurement fixes it to one particular fluid."]'::jsonb, 1, 'Both halves matter, and the pattern runs through the series: the simulation course stated its clipping convention and measured what the other one would give.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 1, 'What was the untuned model given, and what was it asked for?', '["The composition, the C7+ properties and the separator conditions; it was asked for the bubble point, the gas-oil ratio, the gravity and the volume factor.", "All four measured quantities, and it was asked to reproduce them, which is what an armed gate checks.", "The composition and the measured bubble point, and it was asked for the three separator quantities only.", "The composition alone, and it was asked to predict the separator conditions that would optimise the stock tank yield."]'::jsonb, 0, 'It was NOT given the four answers. That is what makes this a prediction the model can fail, and therefore a validation rather than a calibration.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 2, 'The model returns a saturation pressure of 2791.100735294379 psia. What is the error?', '["About minus 5.9 percent, since the model saturates below the pressure the laboratory reported.", "About plus 0.6 percent, taking the difference against the model''s own value rather than the laboratory''s.", "About plus 5.9 percent against the measured 2634.65 psia.", "It cannot be stated as an error, since the model and the laboratory define saturation pressure differently."]'::jsonb, 2, 'Six percent from an untuned equation of state with a single pseudo-component is ordinary. The direction is up, which is the known behaviour for heavy oils.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 3, 'Why does an untuned model saturate high on a heavy oil?', '["Because the Peng-Robinson attraction term is too weak at high molecular weight, so the liquid holds gas less readily.", "Because a single lumped pseudo-component smears the balance between the light and the heavy end, and the first bubble forms because the lightest components want to leave.", "Because the volume shift makes the liquid too dense, which raises the pressure at which a vapour phase can form.", "Because the binary interaction parameters were set to zero for the pseudo-component pairs, which weakens the mixing."]'::jsonb, 1, 'The lump''s characterized properties are an average, and averages are not what controls the onset of a phase split. The engine''s harness records the same direction across the eight Coats and Smart fluids.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 4, 'What does six percent on a saturation pressure do to a depletion forecast?', '["It scales the whole of the pressure history by six percent, since the material balance is anchored at the saturation pressure itself.", "It changes the oil in place by six percent, since the formation volume factor is evaluated at the saturation pressure.", "Very little, since a forecast is dominated by the offtake rate rather than by where the phase boundary sits.", "It moves the year the reservoir crosses its bubble point, and everything about gas handling and well performance shifts with it."]'::jsonb, 3, 'A reservoir at 3000 psia declining a few hundred psi a year crosses at a different time on a 2791 psia model than on a 2635 psia one.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 5, 'The model returns a stock tank gravity of 31.8056416463794 against a measured 40.7. Where does that come from?', '["The Jhaveri-Youngren volume shift on the C7+ pseudo-component, which makes that lump too dense.", "The missing stock tank stage, which leaves intermediates in the liquid and weighs it down.", "The binary interaction parameter with methane, which controls how much light material stays in the stock tank oil.", "The critical pressure of the pseudo-component, which is the least reliable output of the characterization chain."]'::jsonb, 0, 'The engine''s fixture note gives the mechanism: the pure C7+ pseudo recovers a standard-condition specific gravity of 0.9075 against the defined 0.8515.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 6, 'Why does a six percent error in specific gravity become nine API?', '["Because the API scale is logarithmic, so a fixed proportional error becomes a fixed absolute offset in API.", "Because the two errors are independent, the API error also carrying the temperature correction to 60 F.", "Because API is a compressed scale: subtracting 131.5 from 141.5 over the specific gravity magnifies small proportional errors near the middle of the range.", "Because the specific gravity error compounds through the separator train, growing at each of the two stages."]'::jsonb, 2, 'That is a property of the units rather than of the model. It is still a real error: six percent on a stock tank density is six percent on the stock tank volume.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 7, 'Which conclusions does the gravity bias invalidate, and which does it leave alone?', '["It invalidates the saturation pressure as well, since the two share the same characterized pseudo-component.", "It invalidates every stock tank volume and anything commercial, and it leaves the phase equilibrium untouched.", "It invalidates nothing, since a volume shift is applied after the equilibrium and can be removed afterward.", "It invalidates the gas-oil ratio only, since that is the only reported quantity with a stock tank volume in it."]'::jsonb, 1, 'The volume shift cancels in the fugacity ratio, so the model still knows correctly what splits into what. The formation volume factor also divides by a stock tank volume, so it is affected too.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 8, 'Ask the untuned model for a formation volume factor at the study''s reservoir conditions. What comes back?', '["A value about half a percent low, which is the best-matched of the four targets before tuning.", "The liquid-phase volume only, labelled as an approximation, since the vapour has no stock tank basis.", "An error, because a formation volume factor is undefined below the saturation pressure and the call is invalid.", "Nothing: it returns null, because on this model the fluid there is two phase."]'::jsonb, 3, 'The model''s saturation pressure of 2791 psia is ABOVE the stated reservoir pressure of 2634.65, so there is no single-phase oil there and the quantity is undefined.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 9, 'Why is returning null the right behaviour?', '["Because the grading chassis treats a null as unanswered, which is the correct outcome for a field that cannot be computed.", "Because the two-phase volume is the sum of the liquid and the vapour phases, which would far exceed any plausible formation volume factor.", "Because every alternative answers a different question and labels it Bo, and a null with a documented reason is the only honest output.", "Because a caller can then substitute a correlation value, which is what most studies do at that point."]'::jsonb, 2, 'Reporting the liquid-phase volume only, or the total two-phase volume, or an extrapolation of the undersaturated branch, would each be inventing data. Most software returns something.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 10, 'What are the two ways to obtain a comparable Bo anyway?', '["Tune the model until it saturates where the laboratory says, or compare the model''s Bo at ITS bubble point against the laboratory''s at THEIRS.", "Extrapolate the model''s own undersaturated branch downward in pressure, or interpolate between the model''s two nearest single-phase states instead.", "Use the differential liberation value uncorrected, or apply the Amyx correction with the model''s own separator output.", "Raise the stated reservoir pressure until the model is single phase, or lower the temperature until the same happens."]'::jsonb, 0, 'The second is the engine harness''s documented fallback and it is comparing like with like on the quantity both are anchored to. Both are legitimate and the second has to be stated because it is a different comparison.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 11, 'What makes a bias documented rather than a defect?', '["That it is smaller than the tolerance the gate suite applies, which is what the tolerance is for.", "That it is understood, reproducible, recorded and directional.", "That it was present in the original publication of the method, so it is inherited rather than introduced.", "That it can be corrected by a general adjustment, which is what distinguishes a bias from a random error."]'::jsonb, 1, 'A defect is behaviour nobody intended and nobody knows about. The saturation pressure and gravity biases are each understood by mechanism, reproducible run to run, recorded in the gates, and directional across fluids.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 12, 'Why would a general correction for these biases be worse than documenting them?', '["Because the direction is known and the magnitude is fluid-specific, so a general correction would fix this study and break another.", "Because a correction applied inside a library cannot easily be switched off, and some users will need the raw output.", "Because correcting the model would break the armed literature gates, which pin the current behaviour.", "Because the biases partly cancel in the four-target objective, so correcting one would worsen the fit overall."]'::jsonb, 0, 'Corrections fitted to a specific fluid are called tuning, they are done deliberately with stated targets, and they are reported. A correction baked in silently is the same thing without any of the accountability.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 13, 'How should an untuned model be reported?', '["Give the four values with their tolerances, since the tolerances already encode how far the model can be trusted.", "Report only the quantities that agreed, since the disagreeing ones will be corrected by tuning before use.", "Say untuned, then give the comparison target by target, with the mechanism named for each large gap.", "Report the aggregate residual, since a single number is what a reader needs to judge the model''s overall quality."]'::jsonb, 2, 'Four sentences and a reader knows exactly what they have. Errors in a fluid model do not average, so a single aggregate hides which target their question depends on.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 14, 'Why does the untuned comparison stop carrying information after tuning?', '["Because the tuning changes the characterization, so the untuned values can no longer be recomputed.", "Because the tuned model reproduces those four numbers by construction, so agreement with them is no longer evidence.", "Because the tolerances tighten after tuning, so the very same comparison is then being judged against a different standard.", "Because tuning replaces the measured targets with fitted ones, so there is nothing left to compare against."]'::jsonb, 1, 'The untuned run is the last honest look, which is the same argument the simulation course made about running the external comparisons before trusting a deck.'),
  ('fluid', 'intermediate', 'module', 'm04-the-untuned-model', 15, 'What is the check to run on your own fluid before anything else?', '["Run the four separator tests and confirm the model reproduces the optimum pressure the laboratory found.", "Confirm the composition sums to one and the Watson factor is plausible, which validates the two measured inputs.", "Check that the model returns a formation volume factor at reservoir conditions, since a null indicates a problem.", "Compare a measured saturation pressure against the model, and if you have none of your own, say so in the report."]'::jsonb, 3, 'Six percent is ordinary for an untuned model and twenty percent says something is wrong with the composition, the characterization or the temperature. A null Bo is correct behaviour rather than a problem.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 1, 'Standing had 105 points from one region and Vasquez-Beggs over 6000 from everywhere. Which is better?', '["Vasquez-Beggs, since a fit to over six thousand measurements is far better constrained everywhere than a fit to only a hundred of them.", "Standing, since a coherent regional sample produces a tighter fit than a heterogeneous worldwide one.", "Neither in general: they are different trades between breadth and specificity, and knowing which you are buying is the point.", "Whichever was published later, since a later correlation had access to the earlier one''s data as well as its own."]'::jsonb, 2, 'A small coherent sample will do well on oils like its own and has no way of knowing about anything else. A broad heterogeneous one is mediocre everywhere rather than good somewhere.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 2, 'What does having a measurement change about running three correlations?', '["It converts a spread into an error, so you can say which is closer, by how much and in which direction.", "It removes the need to run them, since a measurement supersedes any correlation on the fluid it was made on.", "It lets you select the correlation that agrees, which is the standard way to choose one for a basin.", "It narrows the spread, since the measurement can be added to each correlation''s fitted data set."]'::jsonb, 0, 'Do that on enough fluids and you know something about your basin that no published correlation does. That is what operators with long histories in one area actually have.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 3, 'What does the engine''s validity warning tell you?', '["That the answer is wrong and should be replaced by another correlation covering those conditions.", "That the conditions are outside the range the correlation was fitted over, so the answer is an extrapolation.", "That the scatter of the correlation at these conditions exceeds its published standard error.", "That the correlation has failed to converge, which for an iterative correlation is a genuine numerical failure."]'::jsonb, 1, 'Inside the data the curve is constrained; outside it, the functional form continues and nothing constrains where it goes. Sometimes an extrapolation is fine and the warning cannot tell you which.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 4, 'Why does a validity warning name the correlation rather than just the property?', '["Because the same property is computed by different modules in the black-oil and compositional paths.", "Because a single set of conditions can violate several ranges at once and the reader needs to know which.", "Because the warning text is reused right across the engine and the correlation name is the only distinguishing field in it.", "Because ranges are per correlation, so switching correlations can move you outside a range without changing an input."]'::jsonb, 3, 'A set of conditions that raised no warning under one choice may raise several under another, which is exactly why the correlation has to be named.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 5, 'What does no warning NOT tell you?', '["That the answer is accurate, since scatter within a fitted range can be substantial and the warning is about extrapolation.", "That the correlation was implemented correctly, since a warning function tests conditions rather than code.", "That the conditions are inside the fitted range, since some correlations carry no published range at all for the engine to check.", "That the property is well determined, since a correlation with no independent check is published method at best."]'::jsonb, 0, 'Beal''s dead oil viscosity has factor-of-two scatter well inside its range. The warning is about leaving the evidence, not about the quality of the answer within it.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 6, 'Where do Good Oil''s conditions sit relative to Standing''s fitted range?', '["Outside it on temperature, since 220 F exceeds the range Standing''s Californian oils covered.", "Outside it on gas-oil ratio, since 768 scf/stb is above the maximum in Standing''s data set.", "Inside it, which is necessary and not sufficient, since a point can be inside a data set''s hull and still be poorly constrained.", "It cannot be determined, since Standing did not publish the ranges of his fitted variables."]'::jsonb, 2, 'Standing''s oils covered roughly 16 to 64 API and 20 to 1425 scf/stb, so a 40.7 API oil with 768 scf/stb is comfortably inside. That is what makes the comparison against the measurement meaningful.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 7, 'When is a correlation the right tool?', '["Whenever a compositional analysis is unavailable, since an equation of state cannot run without one.", "For screening and ranking, in early appraisal, as an interpolator on a measured fluid, and for properties the answer does not turn on.", "Whenever the fluid is an ordinary black oil, since the correlations were all fitted to that class.", "Whenever the study is not going to be formally audited by anybody, since a correlated input would never survive a reserves review anyway."]'::jsonb, 1, 'Systematic errors cancel in a comparison, so a ranking survives them. Before a sample exists there is nothing else, and a correlated description with its provenance stated is the correct thing to use.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 8, 'What did this tier find about an untuned model versus a correlation on stock tank gravity?', '["The model did better, since it computes the gravity from composition rather than from a fitted relationship.", "The two were comparable, both landing within a few API of the laboratory value on this fluid.", "The comparison cannot be made, since a correlation does not produce a stock tank gravity at all.", "The correlation would have done better, because a gravity from a separator test is a measurement and one from an untuned model is a construction."]'::jsonb, 3, 'That result inverts a common assumption. The untuned model came out about nine API light, which is far worse than any correlation would be inside its range.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 9, 'What is the rule for when a correlation is good enough?', '["Use one where its error is smaller than the other uncertainties in the calculation, and say you used it.", "Use one wherever a measurement is unavailable, and replace it as soon as one arrives.", "Use one only for properties that do not enter the final answer, and measure everything that does.", "Use one wherever two independent correlations agree, since their agreement bounds the error at the difference."]'::jsonb, 0, 'On a volumetric estimate whose porosity is known to ten percent, a three percent Bo is not the problem. On a mobility ratio that decides a flood design, a viscosity known to a factor of two is.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 10, 'When will a correlation not do?', '["When the fluid falls outside every published correlation''s range, which is the only case a warning can identify.", "When the study will be audited, since a correlated input cannot support a reserves booking.", "When the decision turns on the difference, when the composition is the answer, when the fluid is unusual, or when the composition is being changed.", "When a measurement exists, since a measurement always supersedes a correlation on the same fluid."]'::jsonb, 2, 'Three of those four are about composition and the fourth is about precision. That is the honest summary of when to leave the black-oil world.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 11, 'In what order should the four purchases be made?', '["A tuned model first, since it is the strongest description and the measurements can be added later.", "A measured bubble point, then a separator test, then a full study, then a tuned model on top of it.", "A full study first, since the individual experiments are cheaper together than separately.", "A separator test first, since it defines the stock tank barrel that every other quantity is referenced to."]'::jsonb, 1, 'Each step buys something specific. Buying the last one without the ones before it is what produces a tuned model with nothing to tune against.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 12, 'Why is a company correlation fitted to local data often better than a published one?', '["Because the data set is larger, operators accumulating far more measurements than any single publication.", "Because the fitting is done more carefully, being checked against wells the company can go back to.", "Because the published correlations are decades old and the fitting methods have improved since.", "Because the fluids resemble each other, so a fit to that population is well constrained where it is used."]'::jsonb, 3, 'It is the same trade between breadth and specificity that separates Standing from Vasquez-Beggs, taken to its useful extreme. Such correlations are rarely written up.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 13, 'What is the one thing that is never acceptable?', '["Spending nothing and reporting as though you had spent something.", "Using a correlation on a fluid whose conditions fall outside the correlation''s published range.", "Reporting a correlated value without a range, since a single number implies a precision it does not have.", "Using a black-oil description on a fluid whose composition is available, since the composition is better evidence."]'::jsonb, 0, 'The question is never correlation or measurement in the abstract; it is whether this answer is worth that cost, and the answer is often no. What is not acceptable is concealing which was chosen.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 14, 'What state does this tier leave the model in?', '["One measured fluid and a tuned model that reproduces it, which is the strongest description available.", "Two fluids, one designed and one measured, with correlations checked against both of them.", "One measured fluid, one untuned model, and quantified gaps between them.", "One measured fluid and three correlations, with the spread between the correlations as the uncertainty."]'::jsonb, 2, 'That is the state of the art before tuning, measured rather than asserted. The Expert tier closes the gaps and finds out what closing them costs.'),
  ('fluid', 'intermediate', 'module', 'm05-correlations-against-a-study', 15, 'Why is an untuned equation of state not the general reliable tool?', '["Because it needs a composition, which most fields do not have, so it cannot be applied generally.", "Because it is a construction resting on correlated pseudo-component properties, and this tier measured it doing worse than a separator test.", "Because it is slower than a correlation by orders of magnitude, which rules it out for routine work.", "Because it has no validity range attached, so a user cannot tell when its conditions have left the evidence."]'::jsonb, 1, 'What makes a description reliable is the measurement behind it, whatever machinery sits on top. The general tool is not the reliable tool.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Capstone field 1 asks for the C7+ critical temperature. What are the two likely mistakes?', '["Reporting the critical pressure, which the same correlation returns alongside it, or using the wrong molecular weight.", "Reporting the boiling point, which is the first step of the same chain, or reporting in Fahrenheit rather than Rankine.", "Reporting the tuned value rather than the characterized one, or characterizing from the mixture rather than the plus fraction.", "Reporting the Watson factor, which is dimensionless, or applying the volume shift before the criticals are computed."]'::jsonb, 1, 'The boiling point of 998.28 degR looks like the right kind of number. The check is that a critical temperature must exceed the boiling point, and for a heavy pseudo-component by several hundred degrees.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Capstone field 2 asks for the untuned saturation pressure. What is the likely mistake?', '["Reporting the laboratory''s 2634.65 psia, which is what the model is compared against rather than what it produced.", "Reporting the initial pressure of the reservoir, which for this study happens to equal the bubble point.", "Running the search at 60 F rather than at the reservoir temperature of 220 F, which lowers the answer sharply.", "Reporting the pressure at which the flash first returns a non-zero vapour fraction, which brackets it from below."]'::jsonb, 0, 'The check is that the answer is ABOVE the laboratory value, because this model saturates high on heavy oils, and by a few percent rather than a few tens of percent.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Capstone field 3 asks for the saturation pressure bias as a percentage. What are the two mistakes?', '["Reporting the absolute difference in psia, and using the tuned saturation pressure rather than the untuned one.", "Using the wrong temperature, and taking the difference against the initial pressure rather than the bubble point.", "Taking the percentage of the model''s value rather than the laboratory''s, and getting the sign backwards.", "Averaging the four separator tests first, and then comparing against that average rather than the optimum row."]'::jsonb, 2, 'The two denominators differ enough to matter at this tolerance. The model is the LARGER of the two, so the bias is positive, and the field''s tolerance will not forgive a sign error.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Capstone field 4 asks for the untuned total gas-oil ratio. What is the classic mistake?', '["Reporting the separator gas only, which is the larger of the two contributions and looks like a plausible total.", "Dividing by the separator liquid volume rather than by the stock tank volume, which inflates the ratio.", "Using the wrong separator test row, since the report contains four at different pressures and only one is the optimum.", "Omitting the stock tank stage, which the report does not list but which releases gas that is in the reported total."]'::jsonb, 3, 'Flash once to 114.65 psia and call the liquid the stock tank oil, and the tank gas is absent, the liquid volume is too large, and the answer comes out well below the truth. The check is that the answer is ABOVE the measured 768.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Capstone field 5 asks for the untuned stock tank gravity. What are the two mistakes?', '["Reporting the gravity at reservoir temperature rather than at 60 F, and using the separator liquid rather than the stock tank liquid.", "Reporting the specific gravity rather than the API gravity, and reporting the measured 40.7 rather than the model''s own value.", "Reporting the tuned value, and forgetting that the volume shift is applied after the flash rather than before it.", "Reporting the surface gas gravity, and confusing the stock tank stage with the separator stage in the train."]'::jsonb, 1, 'The check is that the model comes out HEAVIER than the laboratory, so the answer is well below 40.7. If it is near 40.7 you have read the report rather than run the model.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Capstone field 6 asks for the gravity bias. In what form?', '["In API, as model minus measured, so a negative number close to minus nine.", "As a percentage of the measured value, which is the form the saturation pressure bias also takes.", "In specific gravity units, since that is what the volume shift actually moves and the API is derived.", "As an absolute value, since a bias is a magnitude and the direction is stated separately in the report."]'::jsonb, 0, 'API is already a difference scale, so this field does not ask for a percentage. Getting the sign backwards is the other mistake and the model''s oil is the heavier of the two.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'What do three of the six Professional capstone fields have in common?', '["They depend on the characterization, so an error in the C7+ properties propagates into all three of them.", "They can be read directly from the study explorer panel, so no arithmetic outside the panel is needed.", "They ask for a comparison against a measurement rather than for a model output on its own.", "They are all evaluated at the separator conditions rather than at the study''s reservoir conditions."]'::jsonb, 2, 'The commonest way to get a plausible wrong answer on any of the six is to report the measured value where the model value was asked for, or the reverse.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Which two of the four experiments supply a reservoir engineer''s Bo and Rs?', '["The constant composition expansion supplies the shape and the differential liberation supplies the level.", "The separator test supplies both, since it is the only experiment referenced to a stock tank barrel.", "Neither; both come from the compositional analysis run through an equation of state.", "The differential liberation supplies the shape and the separator test supplies the level."]'::jsonb, 3, 'Neither experiment measures them alone. Combining them by the Amyx correction is a modelling choice, exact at the bubble point by construction and approximate below it.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Which number in a PVT report is most often misused, and how?', '["The bubble point, quoted without its temperature, which makes it meaningless for any other thermal condition.", "The differential liberation''s Bod and Rsd, used directly as Bo and Rs when they are referenced to a residual oil rather than a stock tank barrel.", "The total gas-oil ratio, quoted without its separator conditions, which makes it a property of the facilities too.", "The relative volume from the constant composition expansion, mistaken for the formation volume factor."]'::jsonb, 1, 'It is the biggest table in the report and it is labelled with things that look like the properties a simulator wants. Using them directly overstates both by several percent.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What was the untuned model''s largest error, and what causes it?', '["About nine API light on stock tank gravity, from the Jhaveri-Youngren volume shift applied to a single lumped pseudo-component.", "About six percent high on saturation pressure, from the lump smearing the balance between the light and heavy ends.", "About three percent high on total gas-oil ratio, from the separator train''s treatment of the intermediate components.", "The withheld formation volume factor, since a missing answer is the largest error a model can make."]'::jsonb, 0, 'The saturation pressure and gas-oil ratio errors are both ordinary. Nine API is not ordinary in the sense of being acceptable and it IS expected, and the withheld Bo is correct behaviour rather than an error.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Why does the model refuse to report a formation volume factor?', '["Because a formation volume factor requires a differential liberation, which the model does not simulate.", "Because the volume shift makes the liquid density unreliable, so the engine withholds every volumetric output.", "Because its saturation pressure of 2791 psia sits above the 2634.65 psia the laboratory calls reservoir pressure, so the fluid there is two phase on this model.", "Because the separator train has no stage at reservoir conditions, so there is no reservoir volume to divide."]'::jsonb, 2, 'A formation volume factor is reservoir volume of single-phase oil per stock tank barrel. If the fluid there is not a single-phase oil, the quantity is undefined and a null is the honest output.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'What four things make a bias documented rather than a defect?', '["Small, systematic, published and correctable, which are the four properties a regression pin requires.", "Understood, reproducible, recorded and directional.", "Measured, bounded, disclosed and accepted, which is the sequence a limitation goes through before release.", "Known to the author, stated in the manual, flagged at run time and covered by a test."]'::jsonb, 1, 'A defect is behaviour nobody intended and nobody knows about. Each of this tier''s biases is understood by mechanism, reproducible run to run, recorded in the gates, and directional across fluids.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'What did this tier find about correlations versus an untuned equation of state?', '["That an equation of state is better wherever a composition exists, which is what the tier''s comparison established.", "That correlations are better on volume properties and equations of state better on transport properties.", "That the two agree within a few percent on an ordinary black oil, so the choice is a matter of convenience.", "That an untuned equation of state is not automatically better, and on stock tank gravity it is much worse."]'::jsonb, 3, 'A gravity from a separator test is a measurement and a gravity from an untuned model is a construction. That result inverts a common assumption.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'What does the Expert tier do with this tier''s four gaps?', '["Tunes four bounded knobs against the same four measurements, closing three of them and making one worse.", "Corrects them by a general adjustment derived from the eight Coats and Smart fluids in the gate suite.", "Splits the plus fraction until the extra pseudo-components remove the biases at their source.", "Reports them as the model''s stated accuracy, since an untuned model cannot be improved without more data."]'::jsonb, 0, 'Three targets improve and the formation volume factor, which was the best-matched target before tuning, is the one the joint fit gives up.'),
  ('fluid', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'A model and a measurement disagree. What does this tier say to do first?', '["Always prefer the measurement, since a laboratory value is the strongest evidence a fluid description can carry.", "Always tune the model, since a model that disagrees with the data it has is not fit to be asked about anything else.", "When a model and a measurement disagree, find out the direction and the mechanism before deciding which is wrong.", "Always report both, since a reader can then form their own view about which to rely on."]'::jsonb, 2, 'This tier''s biases were both understood before they were measured, which turned two alarming numbers into two documented ones. A disagreement with no mechanism is where the work is.'),
  ('fluid', 'intermediate', 'final', null, 1, 'How many distinct experiments does a reservoir fluid study normally contain?', '["One, run at a sequence of pressures, from which everything else is derived by interpolation.", "Four or five, each answering a different question about the same sample.", "Two, a depletion sequence and a separator test, reported in different units for different readers.", "As many as the client commissions, since a study is assembled from a menu rather than a standard set."]'::jsonb, 1, 'A compositional analysis, a constant composition expansion, a differential liberation, separator tests, and often viscosity measurements on a coarser pressure grid.'),
  ('fluid', 'intermediate', 'final', null, 2, 'Why is one experiment not enough?', '["Because the reservoir depletes differentially and the surface separates by flash, and no single procedure represents both.", "Because the pressure range from reservoir conditions to atmospheric is too wide for one apparatus.", "Because replicates are needed to establish the repeatability of each reported quantity.", "Because the light and heavy ends require different analytical techniques and therefore separate runs."]'::jsonb, 0, 'In the reservoir, gas that comes out of solution moves away from the oil it left. At the surface the whole stream separates together in equilibrium at the separator''s conditions.'),
  ('fluid', 'intermediate', 'final', null, 3, 'What single number does a constant composition expansion exist to produce?', '["The solution gas ratio, from the gas collected at each pressure step of the expansion.", "The formation volume factor, from the cell volume measured against a stock tank reference.", "The oil compressibility, from the slope of relative volume below the bubble point.", "The bubble point."]'::jsonb, 3, 'It is read from the break in the plot of pressure against total volume. Nothing is removed, so no gas is collected, and relative volume is referenced to the bubble point rather than to a stock tank barrel.'),
  ('fluid', 'intermediate', 'final', null, 4, 'Two cell experiments run at reservoir temperature. What separates them?', '["The pressure steps are small enough that each stage is reversible, which is what differential means here.", "The volumes are reported as differences from the bubble point rather than as absolute cell volumes.", "The liberated gas is removed at each pressure step, so the remaining liquid is progressively stripped of light components.", "The gas and the liquid are analysed separately at each step, which differentiates their compositions."]'::jsonb, 2, 'That removal is why the process imitates the reservoir: free gas above its critical saturation flows faster than the oil and separates from the oil that released it.'),
  ('fluid', 'intermediate', 'final', null, 5, 'Why does a differential Bod overstate Bo?', '["Because it divides by a residual oil at 60 F, which is smaller than a stock tank barrel from a well-staged separator train.", "Because it is measured at reservoir temperature while a stock tank barrel is defined at 60 F.", "Because it includes the liberated gas volume in the numerator, which a stock tank definition excludes.", "Because it is reported before the Amyx correction, which removes the double counting of the intermediates."]'::jsonb, 0, 'Differential liberation strips more of the intermediate components, so the residual volume is the smaller reference. Take a differential Bod of 1.6, use it as Bo, and you have overstated it by several percent.'),
  ('fluid', 'intermediate', 'final', null, 6, 'A differential curve and a separator test have to be combined. By what rule?', '["Averages the differential and the flash results, weighted by how much of the journey each represents.", "Rescales the differential curve to pass exactly through the separator test''s value at the bubble point, keeping the differential shape below it.", "Converts the differential gas volumes to a stock tank basis and leaves the liquid volumes untouched.", "Interpolates between the two experiments at every pressure using the liberated gas gravity as the weight."]'::jsonb, 1, 'It is exact at the bubble point by construction and approximate everywhere else: a shape from one experiment anchored to a level from another.'),
  ('fluid', 'intermediate', 'final', null, 7, 'Of everything a separator test reports, what is the load-bearing definition?', '["The optimum separator pressure for the field''s facilities, which is a design output rather than a fluid property.", "The gas gravity for the black-oil correlations, since the first stage releases the lightest gas.", "What a stock tank barrel of this fluid is, which is the denominator of every reservoir volume the study quotes.", "The producing gas-oil ratio the wells will show, which is what a history match is compared against."]'::jsonb, 2, 'Change the separator train and the oil in place in stock tank barrels changes, on identical rock and identical fluid, because a stock tank barrel has become a different amount of matter.'),
  ('fluid', 'intermediate', 'final', null, 8, 'The Professional tier works on one measured fluid. Where does it come from?', '["A reservoir fluid study on Good Oil Co. Well No. 4 in Texas, reproduced in McCain and in Whitson and Brule.", "An SPE benchmark fluid published so that compositional simulators could all be compared against one another.", "The engine''s own fixture, built to exercise the near-critical branch of its phase envelope tracer.", "A study of the Ekene reservoir commissioned so this course would have a measured fluid to work on."]'::jsonb, 0, 'Three textbooks reproduce one report. It is complete and unremarkable, which is exactly what a teaching example needs.'),
  ('fluid', 'intermediate', 'final', null, 9, 'The report quotes pressures in psig on a 14.65 psia base. A reported 2620 psig is what?', '["2634.7 psia, using the more usual atmospheric base of 14.7 psia.", "2605.35 psia, since a gauge pressure is an absolute pressure less the base.", "It cannot be converted without knowing the elevation of the laboratory.", "2634.65 psia."]'::jsonb, 3, 'A study reproduced with the wrong base is out by about 15 psi everywhere, which is small enough to look like scatter.'),
  ('fluid', 'intermediate', 'final', null, 10, 'Methane is 0.3647 and C7+ is 0.3329. What kind of fluid is this?', '["A volatile oil, since a black oil would have methane well below 0.3 and a much larger heavy fraction.", "A black oil, since a condensate has methane above 0.7 and C7+ below 0.05 and a volatile oil sits between.", "A gas condensate, since the methane fraction is the largest single entry in the analysis.", "It cannot be determined from the composition alone without knowing where the reservoir sits on the envelope."]'::jsonb, 1, 'Reading those two numbers first is the quickest way to know what kind of fluid a report describes.'),
  ('fluid', 'intermediate', 'final', null, 11, 'How much of this fluid does the single C7+ entry carry?', '["A third of the moles and about the same share of the mass, since molecular weight cancels in a mole fraction.", "A tenth of the moles and a third of the mass, which is typical for the heavy end of a black oil.", "A third of the moles and something over two thirds of the mass.", "It cannot be stated in mass terms, since a lumped fraction has no single molecular weight."]'::jsonb, 2, 'Its molecular weight is 218 against methane''s 16. One entry out of eleven carries most of the fluid, and its properties come from two measurements and six correlations.'),
  ('fluid', 'intermediate', 'final', null, 12, 'Nobody analyses a wellstream directly. How is the reported composition produced?', '["By recombining separator gas and separator liquid in the ratio the separator test measured.", "By sampling the wellstream downhole above the bubble point, which is what makes a sample representative.", "By chromatography on one surface sample, corrected to reservoir conditions using the formation volume factor.", "By fitting a distribution to the C7+ properties and integrating it over carbon number."]'::jsonb, 0, 'That means the composition depends on the separator test being right, and a recombination at the wrong gas-oil ratio is systematically wrong in the light end.'),
  ('fluid', 'intermediate', 'final', null, 13, 'The report lists one separator stage. How many flash stages does reproducing it need?', '["One, since the report lists one and the tank is where oil ends up rather than a separation step.", "Three, since the fluid must first be flashed from reservoir conditions to the separator inlet.", "Four, one for each of the separator tests the report contains, run from high pressure to low.", "Two: the separator at 114.65 psia and the stock tank at 14.65 psia."]'::jsonb, 3, 'The stock tank is a flash stage the report does not call one, because liquid arriving at 14.65 psia from 114.65 psia releases gas, and that gas is in the reported 768 scf/stb.'),
  ('fluid', 'intermediate', 'final', null, 14, 'Omit the stock tank stage. What happens?', '["The gas-oil ratio comes out too high, since all the gas is attributed to the one remaining stage.", "The gas-oil ratio comes out too low, the stock tank volume too large, the formation volume factor too small, and nothing fails.", "The calculation fails at initialisation, since a train must terminate at atmospheric pressure.", "Nothing measurable changes, since the tank releases only a few percent of the total gas."]'::jsonb, 1, 'The model runs and produces a full set of numbers, every one of them wrong. It is a reading error rather than a physics error, which is what makes it the classic one.'),
  ('fluid', 'intermediate', 'final', null, 15, 'A pseudo-component needs eight properties. What are the inputs?', '["A fitted molecular weight distribution, integrated over carbon number for each property.", "A lookup against the nearest normal alkane by molecular weight, corrected for aromaticity.", "Two measured numbers, a molecular weight of 218 and a specific gravity of 0.8515, through six published correlations.", "The mixture''s own critical properties, scaled by the heavy end''s share of the mass."]'::jsonb, 2, 'Eight numbers come out of two: boiling point, critical temperature and pressure, acentric factor, volume shift, critical volume, parachor and the Watson factor.'),
  ('fluid', 'intermediate', 'final', null, 16, 'The characterization steps are not independent. What consumes what?', '["Boiling point, then the criticals, then the acentric factor, each step consuming the last one''s output.", "The criticals first from molecular weight, then the boiling point, then the acentric factor from both.", "All three in parallel from the two measured inputs, since each has its own independent correlation.", "The acentric factor first from the specific gravity, then the criticals, then the boiling point by inversion."]'::jsonb, 0, 'Uncertainty therefore compounds in a specific direction, and a measured boiling point short-circuits the least constrained link.'),
  ('fluid', 'intermediate', 'final', null, 17, 'The Watson K comes out at 11.73724869095868. What does that say?', '["An unusually aromatic heavy end, which would explain the model''s later trouble with liquid density.", "A normal, slightly naphthenic crude heavy end, which is the free sanity check on the two measured inputs.", "That the molecular weight and specific gravity are inconsistent with any ordinary crude.", "Nothing useful at all, since the Watson factor is a refining quantity without meaning for a reservoir fluid."]'::jsonb, 1, 'Around 12.5 means paraffinic, 11.5 naphthenic and 10 aromatic. A value of 9 or 14 would say the two inputs disagree and the arithmetic should be checked before the model runs.'),
  ('fluid', 'intermediate', 'final', null, 18, 'What does the acentric factor control in the equation of state?', '["The covolume, so that a less spherical molecule occupies proportionally more space.", "The binary interaction parameter against methane, which is why heavy components need large values.", "The critical compressibility, corrected from the two-parameter value toward the real one.", "How fast the attraction term weakens with temperature, through kappa in the alpha function."]'::jsonb, 3, 'That is its whole role. Good Oil''s C7+ comes out at 0.6690835265426222, against methane near 0.011 and normal decane near 0.49.'),
  ('fluid', 'intermediate', 'final', null, 19, 'A volume shift improves densities and disturbs no phase split. How can both be true?', '["Because it is applied after the flash converges, so it cannot influence an iteration already finished.", "Because the shifts are small enough that their effect falls below the solver''s convergence tolerance.", "Because it changes every component''s fugacity in a phase by the same factor, so the ratio across the phases and the split are untouched.", "Because it applies only to the liquid phase, and the equilibrium condition is carried by the vapour."]'::jsonb, 2, 'Most corrections trade one error for another. This one improves densities and provably leaves the phase behaviour alone.'),
  ('fluid', 'intermediate', 'final', null, 20, 'The volume shift is a published correlation correctly applied. Why is the result still wrong?', '["It was fitted to pure hydrocarbons and well-defined fractions, and a single lump standing for a whole C7+ distribution is neither.", "It was fitted at atmospheric conditions and is applied at 220 F and 2634.65 psia, far outside its range.", "It was fitted for paraffins and this heavy end is naphthenic, as the Watson factor already showed.", "It assumes a shift constant with pressure, which is poor near the saturation pressure."]'::jsonb, 0, 'The engine''s fixture note gives the mechanism: the pure C7+ pseudo recovers a standard-condition specific gravity of 0.9075 against the defined 0.8515.'),
  ('fluid', 'intermediate', 'final', null, 21, 'What does splitting the plus fraction cost?', '["Computational cost, since a six-component split multiplies every flash by roughly six.", "Unmeasurable choices about the distribution and the cut points, more parameters to tune, and a model nobody can check.", "Compatibility, since a split composition can no longer be compared against the reported analysis.", "Accuracy at the light end, since the extra components dilute the identified species'' mole fractions."]'::jsonb, 1, 'A split that reproduces the study perfectly may be doing so by construction rather than by physics, and a regression with that much freedom will fit the noise.'),
  ('fluid', 'intermediate', 'final', null, 22, 'What was the untuned model NOT given?', '["The separator conditions, which it had to infer from the reported total gas-oil ratio.", "The C7+ properties, which it characterized from the reported composition alone.", "The reservoir temperature, which it took from the study''s stated bubble point conditions.", "The four measured answers it was asked to predict."]'::jsonb, 3, 'That is what makes this a prediction the model can fail, and therefore a validation rather than a calibration.'),
  ('fluid', 'intermediate', 'final', null, 23, 'The model returns 2791.100735294379 psia against a measured 2634.65. What is the error?', '["About plus 5.9 percent, which is ordinary for an untuned model with a single pseudo-component.", "About minus 5.9 percent, since the model saturates below the laboratory value.", "About plus 0.6 percent, taking the difference against the model''s own value.", "About plus 15 psia, which is simply the pressure base difference rather than any modelling error."]'::jsonb, 0, 'The direction is up, which is the known behaviour for heavy oils: a single lumped pseudo-component smears the balance between the light and heavy ends.'),
  ('fluid', 'intermediate', 'final', null, 24, 'The model returns 31.8056416463794 API against a measured 40.7. Where does that come from?', '["The missing stock tank stage, which leaves intermediates in the liquid and weighs it down.", "The binary interaction parameter with methane, which controls how much light material stays in the tank oil.", "The Jhaveri-Youngren volume shift on the C7+ pseudo-component, which makes that lump too dense.", "The critical pressure of the pseudo-component, the least reliable output of the characterization chain."]'::jsonb, 2, 'The pure C7+ pseudo recovers a standard-condition specific gravity of 0.9075 against the defined 0.8515, and a six percent error in specific gravity becomes nine API because the scale is compressed.'),
  ('fluid', 'intermediate', 'final', null, 25, 'Which conclusions does the gravity bias leave untouched?', '["The stock tank volumes, since the shift is applied to the reservoir liquid rather than the tank liquid.", "The phase equilibrium, because the volume shift cancels in the fugacity ratio.", "The total gas-oil ratio, since gas volumes are unaffected by a liquid density correction.", "None of them, since a density error propagates into every quantity the separator train reports."]'::jsonb, 1, 'The model still knows correctly what splits into what. What it gets wrong is the density of the liquid, and every stock tank volume inherits that.'),
  ('fluid', 'intermediate', 'final', null, 26, 'The model returns null for the formation volume factor. Why?', '["Because its saturation pressure of 2791 psia is above the 2634.65 psia the laboratory calls reservoir pressure, so the fluid there is two phase.", "Because a formation volume factor needs a differential liberation, which the model does not simulate.", "Because the separator train has no stage at reservoir conditions to divide a reservoir volume by.", "Because the volume shift makes liquid densities unreliable, so the engine withholds volumetric outputs."]'::jsonb, 0, 'A formation volume factor is reservoir volume of single-phase oil per stock tank barrel. If the fluid there is not a single-phase oil, the quantity is undefined.'),
  ('fluid', 'intermediate', 'final', null, 27, 'Why is a null the right output rather than a number?', '["Because the grading chassis treats a null as unanswered, which is the correct outcome here.", "Because a caller can then substitute a correlation value, which is what most studies do.", "Because the two-phase volume would exceed any plausible formation volume factor and mislead a reader.", "Because every alternative answers a different question and labels it Bo."]'::jsonb, 3, 'Reporting the liquid volume only, the total two-phase volume, or an extrapolated undersaturated branch would each be inventing data. Most software returns something.'),
  ('fluid', 'intermediate', 'final', null, 28, 'Two models each carry a nine API error. What separates a documented one from a defect?', '["That it is smaller than the tolerance the gate applies, which is what the tolerance exists for.", "That it was present in the original publication of the method, so it is inherited rather than introduced.", "That it is understood, reproducible, recorded and directional.", "That it can be removed by a general correction, which is what separates a bias from random error."]'::jsonb, 2, 'A defect is behaviour nobody intended and nobody knows about. Each of these is understood by mechanism, reproducible, recorded in the gates, and directional across fluids.'),
  ('fluid', 'intermediate', 'final', null, 29, 'Standing had 105 points from one region, Vasquez-Beggs over 6000 from everywhere. Which is better?', '["Vasquez-Beggs, since more measurements always means a better constrained fit.", "Neither in general; they are different trades between breadth and specificity.", "Standing, since a coherent regional sample gives a tighter fit than a heterogeneous one.", "Whichever was published later, having had access to the earlier data as well as its own."]'::jsonb, 1, 'A small coherent sample does well on oils like its own. A broad heterogeneous one is mediocre everywhere rather than good somewhere.'),
  ('fluid', 'intermediate', 'final', null, 30, 'What does a measurement change about running three correlations?', '["It converts a spread into an error, so you can say which is closer, by how much and in which direction.", "It removes the need to run them at all, since a measurement always supersedes a correlation on its own fluid.", "It lets you pick the correlation that agrees, which is how a correlation is chosen for a basin.", "It narrows the spread, the measurement being added to each correlation''s fitted data."]'::jsonb, 0, 'Do that on enough fluids and you know something about your basin that no published correlation does.'),
  ('fluid', 'intermediate', 'final', null, 31, 'What does a validity warning tell you?', '["That the answer is wrong and another correlation should be used for those conditions.", "That the correlation''s scatter at these conditions exceeds its published standard error.", "That the correlation failed to converge, which for an iterative form is a numerical failure.", "That the answer is an extrapolation beyond the fitted data."]'::jsonb, 3, 'Inside the data the curve is constrained; outside it, the functional form continues and nothing constrains where it goes. The warning cannot tell you whether the extrapolation is fine.'),
  ('fluid', 'intermediate', 'final', null, 32, 'A calculation raises no validity warnings at all. What has NOT been established?', '["That the implementation is correct, since a warning function tests conditions rather than code.", "That the conditions are inside the range, since some correlations publish no range at all.", "That the answer is accurate, since scatter within a fitted range can be substantial.", "That the property is well determined, since a correlation has no independent check by definition."]'::jsonb, 2, 'Beal''s dead oil viscosity has factor-of-two scatter well inside its range. The warning is about leaving the evidence, not about quality within it.'),
  ('fluid', 'intermediate', 'final', null, 33, 'Name the situations in which reaching for a correlation is the correct engineering call.', '["Whenever no compositional analysis exists, since an equation of state cannot run without one.", "For screening and ranking, in early appraisal, as an interpolator on a measured fluid, and where the answer does not turn on it.", "Whenever the fluid is an ordinary black oil, which is what the correlations were all fitted to.", "Whenever speed matters, since a correlation is orders of magnitude faster than a flash."]'::jsonb, 1, 'Systematic errors cancel in a comparison, so a ranking survives them. Before a sample exists there is nothing else.'),
  ('fluid', 'intermediate', 'final', null, 34, 'On stock tank gravity specifically, which loses: the untuned model or a separator test?', '["The correlation would have done better, because a gravity from a separator test is a measurement and one from an untuned model is a construction.", "The model did better, computing the gravity from composition rather than a fitted relationship.", "The two were comparable, both landing within a few API of the laboratory value.", "The comparison cannot be made, since a correlation does not produce a stock tank gravity."]'::jsonb, 0, 'That result inverts a common assumption. The untuned model came out about nine API light, far worse than a correlation inside its range.'),
  ('fluid', 'intermediate', 'final', null, 35, 'A budget allows four things to be bought in sequence. What order?', '["A tuned model first, since it is the strongest description and measurements can follow.", "A full study first, since the experiments cost less together than separately.", "A separator test first, since it defines the stock tank barrel everything is referenced to.", "A measured bubble point, then a separator test, then a full study, then a tuned model."]'::jsonb, 3, 'Each step buys something specific. Buying the last one without the ones before it produces a tuned model with nothing to tune against.'),
  ('fluid', 'intermediate', 'final', null, 36, 'Capstone field 1 asks for the C7+ critical temperature. What is the check?', '["It must be below the mixture''s own critical temperature, which the envelope tracer reports separately.", "It must fall between the critical temperatures of decane and eicosane, which bracket this molecular weight.", "It must exceed the boiling point, and for a heavy pseudo-component by several hundred degrees Rankine.", "It must be consistent with the Watson factor, which is computed from the same two measured inputs."]'::jsonb, 2, 'The boiling point of 998.28 degR is the first step of the same chain and looks like the right kind of number, which is why the check is worth stating.'),
  ('fluid', 'intermediate', 'final', null, 37, 'Capstone field 4 asks for the untuned total gas-oil ratio. What is the check?', '["The answer is ABOVE the measured 768 scf/stb; an answer below it almost certainly has one stage.", "The answer is below the measured 768, since an untuned model under-predicts gas liberation.", "The answer equals the separator gas plus the tank gas, which is an identity rather than an actual check.", "The answer falls between the four separator tests the report contains, which bracket it."]'::jsonb, 0, 'Omitting the stock tank stage leaves the tank gas out of the total and inflates the liquid volume, so the answer comes out well below the truth.'),
  ('fluid', 'intermediate', 'final', null, 38, 'Capstone field 5 asks for the untuned stock tank gravity. What is the check?', '["The model comes out lighter than the laboratory, since an untuned model under-predicts the heavy end.", "The model comes out heavier than the laboratory, so the answer is well below 40.7 API.", "The answer equals the specific gravity converted through the API relation at reservoir temperature.", "The answer falls within the tolerance the engine''s own literature gate applies, which is 10 API."]'::jsonb, 1, 'If the answer is near 40.7 you have read the report rather than run the model. The gate tolerance is set just above the observed bias to pin it rather than to certify it.'),
  ('fluid', 'intermediate', 'final', null, 39, 'What do three of the six Professional fields have in common?', '["They depend on the characterization, so a C7+ error propagates into all three of them.", "They can be read straight from the study explorer panel without any arithmetic outside it.", "They are evaluated at the separator conditions rather than at the study''s reservoir conditions.", "They ask for a comparison against a measurement rather than for a bare model output on its own."]'::jsonb, 3, 'The commonest way to get a plausible wrong answer on any of the six is to report the measured value where the model value was asked for, or the reverse.'),
  ('fluid', 'intermediate', 'final', null, 40, 'Which two experiments supply a reservoir engineer''s Bo and Rs?', '["The differential liberation supplies the shape and the separator test supplies the level.", "The constant composition expansion supplies the shape and the differential liberation the level.", "The separator test supplies both, being the only experiment referenced to a stock tank barrel.", "Neither; both come from the composition run through an equation of state."]'::jsonb, 0, 'Neither measures them alone. Combining them by the Amyx correction is a modelling choice, exact at the bubble point and approximate below it.'),
  ('fluid', 'intermediate', 'final', null, 41, 'Which number in a PVT report is most often misused?', '["The bubble point, quoted without its temperature and therefore meaningless elsewhere.", "The total gas-oil ratio, quoted without its separator conditions and therefore incomplete.", "The differential liberation''s Bod and Rsd, used directly when they are referenced to a residual oil.", "The relative volume, mistaken for the formation volume factor because both of them are dimensionless."]'::jsonb, 2, 'It is the biggest table in the report and it is labelled with things that look like what a simulator wants. Using them directly overstates both by several percent.'),
  ('fluid', 'intermediate', 'final', null, 42, 'What habit is this tier trying to build?', '["Always prefer the measurement, since a laboratory value is the strongest evidence available.", "When a model and a measurement disagree, find the direction and the mechanism before deciding which is wrong.", "Always tune the model, since one that disagrees with its own data is simply not fit to be asked about anything else.", "Always report both, so that a reader can form their own view about which to rely on."]'::jsonb, 1, 'This tier''s biases were understood before they were measured, which turned two alarming numbers into two documented ones. A disagreement with no mechanism is where the work is.');
